def organisations_from_names(apps, schema_editor):
    """Each organisation name typed on a customer becomes an Organisation with its own Org ID (customers with the
    same name, ignoring case and spaces, share one)."""
    Customer = apps.get_model("licensing", "Customer")
    Organisation = apps.get_model("licensing", "Organisation")
    made = {}
    for customer in Customer.objects.exclude(org="").order_by("created", "pk"):
        key = " ".join(customer.org.split()).lower()
        if key not in made:
            org = Organisation.objects.create(name=customer.org.strip())
            org.org_id = f"ORG-{org.pk:05d}"
            org.save(update_fields=["org_id"])
            made[key] = org
        customer.organisation = made[key]
        customer.save(update_fields=["organisation"])


